/// The x (pt) of the first glyph of the first glyph run on page `p` whose text (spaces dropped) starts with `text`.
fn x_of(l: &Layout, p: usize, text: &str) -> Option<f64> {
    let page = &l.pages[p].page;
    let cols = &page.list.glyphs;
    let want: String = text.chars().filter(|&c| !uo_jsnum::text::is_js_space(c)).collect();
    for it in &page.list.items {
        let Item::Glyphs { glyphs, .. } = it else { continue };
        let s = glyphs.start as usize;
        let t: String = cols.cp[s..s + glyphs.len as usize]
            .iter()
            .filter_map(|&c| char::from_u32(c))
            .filter(|&c| !uo_jsnum::text::is_js_space(c))
            .collect();
        if t.starts_with(&want) {
            return Some(cols.x[s] / 20.0);
        }
    }
    None
}

fn fixture(name: &str) -> Vec<u8> {
    std::fs::read(PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fidelity").join(name)).unwrap()
}

/// Item 2 on B's `cell-lic1` (a table with a text box in a cell, a package without `settings.xml`): Word (mode 12) puts the
/// first cell's text (beside the box) at x 220.01 pt and the box's text at 100.58 pt; the same document with a mode-15 settings part
/// at 225.65 / 106.22 (measured, the planner's probe). Word's rules give Word's; `ts_strict()` the frozen TS's mode 15.
#[test]
fn cell_lic1_without_settings_is_laid_out_in_mode_12() {
    let bytes = fixture("cell-lic1-nosettings.docx");
    let w = lay(&bytes, &opts());
    let t = lay(&bytes, &opts().ts_strict());
    let (wc, wb) = (x_of(&w, 0, "celula 00").unwrap(), x_of(&w, 0, "caixa 1").unwrap());
    let (tc, tb) = (x_of(&t, 0, "celula 00").unwrap(), x_of(&t, 0, "caixa 1").unwrap());
    assert!((wc - 220.01).abs() <= 0.3 && (wb - 100.58).abs() <= 0.3, "Word's rules: cell {wc}, box {wb} (Word 220.01, 100.58)");
    assert!((tc - 225.65).abs() <= 0.3 && (tb - 106.22).abs() <= 0.3, "ts_strict: cell {tc}, box {tb} (mode 15: 225.65, 106.22)");
}

/// The tab-led line geometry of page 0 (each line's x0/x1 and text): what a default tab stop moves.
fn tab_geometry(l: &Layout) -> Vec<String> {
    engine_lines(l).pages.first().map(|p| p.iter().map(|x| format!("{:.2}-{:.2} {}", x.x0, x.x1, x.text)).collect()).unwrap_or_default()
}

/// Item 2, fix round 1 (reviewer W/1): Word's 708 tw for a missing `w:defaultTabStop` is a FALLBACK — an explicit value
/// the user sets (`setDefaultTabStop`) wins, also 720 (the frozen TS model's value), and `getDefaultTabStop` answers the
/// value the layout uses. Before the fix the session wrote the setting but the layout kept 708 (the reader's fact), and
/// `getDefaultTabStop` said 720. `OpenOptions::ts_missing_settings` keeps the frozen TS's answers (720; setting 720 is a
/// no-op there).
#[test]
fn default_tab_stop_of_a_package_without_one_follows_the_session() {
    use std::sync::Arc;
    use uo_docx::session::ops::text_layout::TextLayoutCmd;
    use uo_docx::session::{ClipboardRing, Command, ExecCx, FixedEnv, OpenOptions, Session};
    use uo_docx_layout::oracle::EngineOracle;
    let fonts = OpenFonts::at(&common::repo());
    let lay_view = |v: DocView<'_>| {
        let mut eng = LayoutEngine::with_hyphenation(common::hyph::hyph_registry());
        tab_geometry(eng.layout(v, &fonts, &opts()).unwrap())
    };
    for name in ["ns-tabs-none", "ns-tabs-c15notab", "ns-tabs-bare"] {
        let bytes = std::fs::read(oracle_dir("nosettings").join(format!("{name}.docx"))).unwrap();
        let mut s = Session::open(bytes.clone(), OpenOptions::default(), Box::new(FixedEnv::default())).unwrap();
        let mut oracle = EngineOracle::new(&fonts, Arc::clone(&common::hyph::hyph_registry()), opts());
        let mut clip = ClipboardRing::default();
        assert_eq!(s.default_tab_stop_now(), 708.0, "{name}: getDefaultTabStop at load = the layout's 708");
        let load = lay_view(s.view());
        // the session's layout at load = the reader's under Word's rules (708)
        assert_eq!(load, tab_geometry(&lay(&bytes, &opts())), "{name}: session at load");
        let mut set = |s: &mut Session, tw: f64| {
            s.exec(
                Command::TextLayout(TextLayoutCmd::SetDefaultTabStop { twips: tw }),
                &mut ExecCx { layout: &mut oracle, clipboard: &mut clip },
            )
            .unwrap();
        };
        set(&mut s, 720.0);
        assert_eq!(s.default_tab_stop_now(), 720.0, "{name}: 720 can be chosen");
        let at720 = lay_view(s.view());
        assert_ne!(at720, load, "{name}: setDefaultTabStop(720) moves the tabs");
        set(&mut s, 1440.0);
        assert_eq!(s.default_tab_stop_now(), 1440.0);
        let at1440 = lay_view(s.view());
        assert_ne!(at1440, at720, "{name}: setDefaultTabStop(1440) moves the tabs");
        // undo twice: back to the loaded 708 (the TS's restore applies the loaded value)
        for _ in 0..2 {
            s.undo(&mut ExecCx { layout: &mut oracle, clipboard: &mut clip });
        }
        assert_eq!(s.default_tab_stop_now(), 708.0, "{name}: undone");
        assert_eq!(lay_view(s.view()), load, "{name}: undone, the loaded layout");
        // the frozen TS's reading (strict replays)
        let o = OpenOptions { ts_missing_settings: true, ..OpenOptions::default() };
        let t = Session::open(bytes, o, Box::new(FixedEnv::default())).unwrap();
        assert_eq!(t.default_tab_stop_now(), 720.0, "{name}: ts_missing_settings = the TS model's 720");
    }
}

/// Item 2, fix round 1 (reviewer W/2): the attribution of the two `editor_switch_format` differences on documents without
/// `word/settings.xml` (the d3 fixtures `tables.docx` and `hyperlinks.docx`), in the session the editor runs: under Word's
/// rules with ONLY `ts_missing_settings_mode15` switched on, the layout equals `ts_strict()`'s — the ruler frame of the
/// first cell's line (`getRulerInfo` reads `LineGeom::frame`) and every painted page — and differs from Word's rules.
/// `tables.docx`: the frame 1701..3485 (Word's mode 12: the cell's text at the margin; the TS's 1701..10205);
/// `hyperlinks.docx` with a 2×2 table inserted at its start (the `print-cell` scenario): the table placement.
#[test]
fn item2_attribution_of_the_editor_harness_documents() {
    use std::sync::Arc;
    use uo_docx::session::ops::tables::{TableCmd, TableLayoutIn};
    use uo_docx::session::{ClipboardRing, Command, ExecCx, FixedEnv, OpenOptions, Session};
    use uo_docx_layout::oracle::EngineOracle;
    let fonts = OpenFonts::at(&common::repo());
    let d3 = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../uo-docx/tests/parity/d3/fixtures");
    let only_item2 = LayoutOptions { ts_missing_settings_mode15: true, ..opts() };
    // (x, frame) of every line — the ruler reads `x + frame` — and every painted page
    // (x, frame) per line, debug text per page
    type Lines = Vec<(f64, Option<(f64, f64)>)>;
    let run = |v: DocView<'_>, o: &LayoutOptions| -> (Lines, Vec<String>) {
        let mut eng = LayoutEngine::with_hyphenation(common::hyph::hyph_registry());
        let l = eng.layout(v, &fonts, o).unwrap();
        let lines = l.pages.iter().flat_map(|p| p.lines.iter().chain(p.content_lines.iter()).map(|g| (g.x, g.frame))).collect();
        (lines, l.pages.iter().map(|p| format!("{:?}", p.page)).collect())
    };
    // tables.docx at load
    let s = Session::open(std::fs::read(d3.join("tables.docx")).unwrap(), OpenOptions::default(), Box::new(FixedEnv::default())).unwrap();
    let (w, t, i2) = (run(s.view(), &opts()), run(s.view(), &opts().ts_strict()), run(s.view(), &only_item2));
    println!(
        "tables.docx first line (x, frame): Word's rules {:?}, ts_strict {:?}, only item 2 {:?}",
        w.0.first(),
        t.0.first(),
        i2.0.first()
    );
    // Word's mode 12: the first cell's text at the margin (x 1701, the table's edge 108 tw to its left); the TS's mode 15: the
    // table's edge at the margin, the text at 1701 + 108
    assert_eq!(w.0.first().copied(), Some((1701.0, Some((0.0, 1784.0)))), "tables.docx: Word's rules");
    assert_eq!(t.0.first().copied(), Some((1809.0, Some((0.0, 1784.0)))), "tables.docx: ts_strict");
    assert_eq!(i2, t, "tables.docx: only item 2's switch gives the TS's layout");
    assert_ne!(w, t);
    // hyperlinks.docx + a 2×2 table inserted at the start (editor_switch_format `print-cell`)
    let mut s =
        Session::open(std::fs::read(d3.join("hyperlinks.docx")).unwrap(), OpenOptions::default(), Box::new(FixedEnv::default())).unwrap();
    let mut oracle = EngineOracle::new(&fonts, Arc::clone(&common::hyph::hyph_registry()), opts());
    let mut clip = ClipboardRing::default();
    s.exec(
        Command::Table(TableCmd::InsertTable {
            rows: 2.0,
            cols: 2.0,
            autofit: None,
            col_width_twips: None,
            layout: TableLayoutIn::default(),
        }),
        &mut ExecCx { layout: &mut oracle, clipboard: &mut clip },
    )
    .unwrap();
    let (w, t, i2) = (run(s.view(), &opts()), run(s.view(), &opts().ts_strict()), run(s.view(), &only_item2));
    println!("hyperlinks.docx + table first line (x, frame): Word's rules {:?}, ts_strict {:?}", w.0.first(), t.0.first());
    assert_eq!(i2, t, "hyperlinks.docx + table: only item 2's switch gives the TS's layout");
    assert_ne!(w.1, t.1, "hyperlinks.docx + table: Word's rules paint the page differently (the mode-12 table placement)");
}

/// The glyph runs of page `p`: (x pt, baseline pt, text).
fn runs_of(l: &Layout, p: usize) -> Vec<(f64, f64, String)> {
    let page = &l.pages[p].page;
    let cols = &page.list.glyphs;
    let mut out = Vec::new();
    for it in &page.list.items {
        let Item::Glyphs { glyphs, y, .. } = it else { continue };
        let s = glyphs.start as usize;
        let t: String = cols.cp[s..s + glyphs.len as usize].iter().filter_map(|&c| char::from_u32(c)).collect();
        out.push((cols.x[s] / 20.0, *y / 20.0, t));
    }
    out
}

/// Item 3 on B's `linked` (two linked boxes in one cell, mode 15; the planner's probe `linked-c15`): Word puts "primeira
/// caixa" in the first box (baseline 100.82 pt, re-measured: the planner's 92.10/129.06 were not baselines) and goes on in
/// the second (137.78 pt); the frozen TS leaves the first box
/// empty and starts the chain in the second (137.79 pt).
#[test]
fn linked_boxes_in_a_cell_start_in_the_first_box() {
    let bytes = fixture("linked-cell-c15.docx");
    let y_of = |l: &Layout, t: &str| runs_of(l, 0).into_iter().find(|r| r.2.replace(' ', "") == t).map(|r| r.1);
    let w = lay(&bytes, &opts());
    let (a, b) = (y_of(&w, "primeiracaixa").unwrap(), y_of(&w, "comumtexto").unwrap());
    assert!((a - 100.82).abs() <= 0.3 && (b - 137.78).abs() <= 0.3, "Word's rules: {a} / {b} (Word 100.82 / 137.78)");
    let t = lay(&bytes, &opts().ts_strict());
    let a = y_of(&t, "primeiracaixa").unwrap();
    assert!((a - 137.79).abs() <= 0.3, "ts_strict: {a} (the frozen TS: 137.79)");
}

