/// Item 4: Word writes its reference error texts in bold (measured in its PDF: LiberationSans-Bold); `ts_strict()` keeps
/// the frozen TS's start-paragraph text. Also the viewer's read (no `sources`): an unterminated body bookmark is in the
/// body index, so the error shows there too.
#[test]
fn ref_errors_are_bold() {
    let bytes = std::fs::read(oracle_dir("refbm").join("rb-unterm.docx")).unwrap();
    for sources in [false, true] {
        let l = lay_read(&bytes, &opts(), sources);
        let page = &l.pages[0].page;
        let cols = &page.list.glyphs;
        let mut found = 0;
        for it in &page.list.items {
            let Item::Glyphs { glyphs, face, .. } = it else { continue };
            let s = glyphs.start as usize;
            let t: String = cols.cp[s..s + glyphs.len as usize].iter().filter_map(|&c| char::from_u32(c)).collect();
            if t.starts_with("Erro!") {
                found += 1;
                assert!(l.resources.faces[face.index()].bold, "sources {sources}: {t:?} is not bold");
            }
        }
        assert_eq!(found, 8, "sources {sources}: the eight error texts of rb-unterm");
        let ts = lay_read(&bytes, &opts().ts_strict(), sources);
        let runs: Vec<String> = runs_of(&ts, 0).into_iter().map(|r| r.2).collect();
        assert!(!runs.iter().any(|t| t.starts_with("Erro!")), "ts_strict: {runs:?}");
    }
}

/// Opt-in (`UO_W7C_ORACLE=<dir of oracle groups>`, e.g. the frozen TS root's `write/packages/docx-layout/test/oracle`,
/// 2,742 documents): "Word agreement may only go up". Every case is laid out with the installed fonts (uo-fonts'
/// oracle policy over the system font index) twice — `ts_strict()` and Word's rules —; where the two differ, both are
/// compared with the case's `.word.json` (pages, line texts, the page of each line, baseline ±0.3 pt, or the group's
/// own tolerance below). Prints the changed cases per group and the Word-equal counts before (TS rules) and after (Word
/// rules); fails when a changed case went from equal to different.
#[test]
fn word_rules_agreement_on_the_oracle() {
    let Ok(root) = std::env::var("UO_W7C_ORACLE") else {
        println!("skipped: set UO_W7C_ORACLE to a directory of oracle groups");
        return;
    };
    use uo_docx_layout::options::{RevisionMode, RevisionView};
    // the per-group tolerances of the frozen TS's oracle.test.ts (24–48) that apply to a line comparison
    let dy_tol = |g: &str| match g {
        "vertalign" => 0.6,
        "notes" | "fnsep" | "fnrefsup" => 0.65,
        "omath" => 0.4,
        _ => 0.3,
    };
    let source: std::sync::Arc<dyn uo_fonts::registry::FaceSource> = uo_fonts::system::SystemFontIndex::shared();
    let registry = std::sync::Arc::new(
        uo_fonts::registry::FontRegistry::new(
            uo_fonts::registry::FontBudget::of(uo_fonts::registry::FontProfile::Desktop),
            uo_fonts::registry::FaceCache::shared(),
        )
        .with_source(source),
    );
    let provider = uo_fonts::policy::provider(&registry, uo_fonts::policy::PolicyName::Oracle).unwrap();
    let mut groups: Vec<_> = std::fs::read_dir(&root).unwrap().flatten().map(|e| e.path()).filter(|p| p.is_dir()).collect();
    groups.sort();
    let (mut total, mut changed, mut before, mut after) = (0usize, 0usize, 0usize, 0usize);
    let mut worse = Vec::new();
    for gdir in groups {
        let g = gdir.file_name().unwrap().to_string_lossy().into_owned();
        let mut names: Vec<String> = std::fs::read_dir(&gdir)
            .unwrap()
            .flatten()
            .filter_map(|e| e.file_name().to_str().and_then(|n| n.strip_suffix(".docx")).map(str::to_owned))
            .collect();
        names.sort();
        let mut g_changed = Vec::new();
        for n in names {
            let Ok(json) = std::fs::read_to_string(gdir.join(format!("{n}.word.json"))) else { continue };
            total += 1;
            let bytes = std::fs::read(gdir.join(format!("{n}.docx"))).unwrap();
            let pkg = uo_opc::Package::open(&bytes, &Default::default(), &Default::default()).unwrap();
            let Ok(doc) = read_document(&pkg, &ReadOptions::default()) else { continue };
            let mut o = opts();
            if n.starts_with("mk-") {
                o.revisions = Some(RevisionView { mode: RevisionMode::All, ..RevisionView::default() });
            }
            let mut eng = LayoutEngine::with_hyphenation(common::hyph::hyph_registry());
            let Ok(ts) = eng.layout(DocView::new(&doc), &*provider, &o.clone().ts_strict()).cloned() else { continue };
            let mut eng = LayoutEngine::with_hyphenation(common::hyph::hyph_registry());
            let Ok(w) = eng.layout(DocView::new(&doc), &*provider, &o).cloned() else { continue };
            if format!("{:?}", ts.pages.iter().map(|p| &p.page).collect::<Vec<_>>())
                == format!("{:?}", w.pages.iter().map(|p| &p.page).collect::<Vec<_>>())
            {
                continue;
            }
            changed += 1;
            let word = word_lines(&json);
            let ok = |c: &Cmp| c.pages_o == c.pages_w && c.matched == c.lines_w && c.same_page == c.matched && c.max_dy <= dy_tol(&g);
            let (b, a) = (ok(&compare(&word, &engine_lines(&ts))), ok(&compare(&word, &engine_lines(&w))));
            before += usize::from(b);
            after += usize::from(a);
            if b && !a {
                worse.push(format!("{g}/{n}"));
            }
            g_changed.push(format!("{n} ({}→{})", if b { "equal" } else { "differs" }, if a { "equal" } else { "differs" }));
        }
        if !g_changed.is_empty() {
            println!("{g}: {}", g_changed.join(", "));
        }
    }
    println!("oracle: {total} cases, {changed} change under Word's rules; Word-equal among them: TS rules {before}, Word rules {after}");
    assert!(worse.is_empty(), "equal to Word with the TS rules, different with Word's: {worse:?}");
}

/// Opt-in (`UO_W7C_ATTR=<dir of .docx>`): which of the Word-over-TS switches changes each document's pages (the harness
/// declarations name the item they come from). Each switch is turned to Word's rule alone over `ts_strict()`.
#[test]
fn attribute_documents_to_the_word_rules() {
    let Ok(dir) = std::env::var("UO_W7C_ATTR") else {
        println!("skipped: set UO_W7C_ATTR");
        return;
    };
    let mut files: Vec<_> =
        std::fs::read_dir(&dir).unwrap().flatten().map(|e| e.path()).filter(|p| p.extension().is_some_and(|x| x == "docx")).collect();
    files.sort();
    type Flip = fn(&mut LayoutOptions);
    let flips: [(&str, Flip); 8] = [
        ("empty_theme", |o| o.ts_empty_theme = false),
        ("pageref_chapter", |o| o.ts_pageref_without_chapter = false),
        ("theme_tint", |o| o.ts_theme_tint = false),
        ("missing_settings", |o| o.ts_missing_settings_mode15 = false),
        ("linked_cell", |o| o.ts_linked_box_cell_chain = false),
        ("ref_bookmarks", |o| o.ts_ref_bookmarks = false),
        ("hyphenation", |o| o.ts_hyphenation_patterns = false),
        ("keep_lines", |o| o.ts_keep_lines_within_page = false),
    ];
    let pages = |l: &Layout| format!("{:?}", l.pages.iter().map(|p| &p.page).collect::<Vec<_>>());
    // `UO_W7C_ATTR_SOURCES=1`: read as the editor does (`sources`: the bookmark marks of a lossless read)
    let sources = std::env::var_os("UO_W7C_ATTR_SOURCES").is_some();
    let lay = |b: &[u8], o: &LayoutOptions| lay_read(b, o, sources);
    // fix round 1 (reviewer W/5): the pages (0-based, the viewer harness's `page N`) each switch changes — a page whose
    // painted content differs, and every page past the shorter layout
    let per_page = |l: &Layout| l.pages.iter().map(|p| format!("{:?}", p.page)).collect::<Vec<_>>();
    for p in files {
        let bytes = std::fs::read(&p).unwrap();
        let base_l = lay(&bytes, &opts().ts_strict());
        let (base, base_p) = (pages(&base_l), per_page(&base_l));
        let mut hit = Vec::new();
        for (n, f) in &flips {
            let mut o = opts().ts_strict();
            f(&mut o);
            let l = lay(&bytes, &o);
            if pages(&l) != base {
                let pp = per_page(&l);
                let changed: Vec<String> =
                    (0..pp.len().max(base_p.len())).filter(|&i| pp.get(i) != base_p.get(i)).map(|i| i.to_string()).collect();
                hit.push(format!("{n} [pages {} → {}; changed {}]", base_p.len(), pp.len(), changed.join(" ")));
            }
        }
        println!("{}: {}", p.file_name().unwrap().to_string_lossy(), if hit.is_empty() { "-".to_owned() } else { hit.join(", ") });
    }
}

/// Opt-in (`UO_W7C_ADHOC=<dir of .docx + .word.json>`): each document against Word with the installed fonts, Word's rules
/// and `ts_strict()` (the record's check of the harness fixtures a Word rule changes).
#[test]
fn adhoc_documents_against_word() {
    let Ok(dir) = std::env::var("UO_W7C_ADHOC") else {
        println!("skipped: set UO_W7C_ADHOC");
        return;
    };
    let source: std::sync::Arc<dyn uo_fonts::registry::FaceSource> = uo_fonts::system::SystemFontIndex::shared();
    let registry = std::sync::Arc::new(
        uo_fonts::registry::FontRegistry::new(
            uo_fonts::registry::FontBudget::of(uo_fonts::registry::FontProfile::Desktop),
            uo_fonts::registry::FaceCache::shared(),
        )
        .with_source(source),
    );
    let provider = uo_fonts::policy::provider(&registry, uo_fonts::policy::PolicyName::Oracle).unwrap();
    let mut files: Vec<_> =
        std::fs::read_dir(&dir).unwrap().flatten().map(|e| e.path()).filter(|p| p.extension().is_some_and(|x| x == "docx")).collect();
    files.sort();
    for p in files {
        let Ok(json) = std::fs::read_to_string(p.with_extension("word.json")) else { continue };
        let word = word_lines(&json);
        let bytes = std::fs::read(&p).unwrap();
        let pkg = uo_opc::Package::open(&bytes, &Default::default(), &Default::default()).unwrap();
        let doc = read_document(&pkg, &ReadOptions::default()).unwrap();
        let mut row = Vec::new();
        for (n, o) in [("word", opts()), ("ts", opts().ts_strict())] {
            let mut eng = LayoutEngine::with_hyphenation(common::hyph::hyph_registry());
            let l = eng.layout(DocView::new(&doc), &*provider, &o).unwrap().clone();
            let c = compare(&word, &engine_lines(&l));
            row.push(format!(
                "{n}: pages {}/{} lines {}/{} same page {} dy {:.2} {:?}",
                c.pages_o, c.pages_w, c.matched, c.lines_w, c.same_page, c.max_dy, c.first_diff
            ));
        }
        println!("{}: {}", p.file_name().unwrap().to_string_lossy(), row.join(" | "));
    }
}

/// Item 1 — OPEN (record uo-bindings.md "Wave 7c — W"): Word's theme tint/shade rounding is not known. The 3,356
/// measured samples (`oracle_w7c/tint/word-samples.tsv`: 48 bases × 34 tint and 34 shade bytes through Word's PDF, plus
/// 92 hex values Word wrote in its own documents) pin how far the frozen TS rule (`applyTintShade`: HSL lightness,
/// channels truncated — the layout and the session use it) is from Word: 2,323 equal. No candidate reproduces Word
/// (best: exact HSL with L′ truncated to 1/1020 and S to 1/1000, 2,662); when one does, it replaces the TS rule behind
/// `ts_theme_tint` and this count becomes 3,356.
#[test]
fn tint_shade_samples_against_the_ts_rule() {
    let data = std::fs::read_to_string(oracle_dir("tint").join("word-samples.tsv")).unwrap();
    let (mut n, mut hit) = (0, 0);
    for line in data.lines().filter(|l| !l.starts_with('#') && !l.is_empty()) {
        let f: Vec<&str> = line.split('\t').collect();
        let (tint, shade) = if f[1] == "tint" { (Some(f[2]), None) } else { (None, Some(f[2])) };
        n += 1;
        if uo_docx::word::apply_tint_shade(f[0], tint, shade) == f[3] {
            hit += 1;
        }
    }
    assert_eq!((hit, n), (2_323, 3_356), "the TS rule against Word's samples");
}

/// Opt-in (`UO_W7C_LINES=<dir>`; item 5, the `hyphword` measurement): for each `<stem>.docx` with a `<stem>.word.json` in
/// `dir`, writes the line texts of Word's PDF and of the Rust layout (open fonts, Word's rules), normalized the same
/// way (`<stem>.word.lines`, `<stem>.rust.lines`), for the per-word hyphenation agreement script.
#[test]
fn dump_lines_for_the_hyphenation_agreement() {
    let Ok(dir) = std::env::var("UO_W7C_LINES") else {
        println!("skipped: set UO_W7C_LINES");
        return;
    };
    let dir = PathBuf::from(dir);
    let mut stems: Vec<String> = std::fs::read_dir(&dir)
        .unwrap()
        .flatten()
        .filter_map(|e| e.file_name().to_str().and_then(|n| n.strip_suffix(".docx")).map(str::to_owned))
        .collect();
    stems.sort();
    let text = |d: &Doc| d.pages.iter().flatten().map(|l| l.text.clone()).collect::<Vec<_>>().join("\n") + "\n";
    for s in stems {
        let Ok(json) = std::fs::read_to_string(dir.join(format!("{s}.word.json"))) else { continue };
        let ours = engine_lines(&lay(&std::fs::read(dir.join(format!("{s}.docx"))).unwrap(), &opts()));
        std::fs::write(dir.join(format!("{s}.word.lines")), text(&word_lines(&json))).unwrap();
        std::fs::write(dir.join(format!("{s}.rust.lines")), text(&ours)).unwrap();
    }
}
